#!/bin/bash
# =========================================================
#  ChaiyaVPN - Web Frontend + Promo Admin API + Wallet System
#  รวม: shop-home / network-packages / login / wallet / admin panel
#        + Flask API (โปรโมชั่น, สมัครสมาชิก/ล็อกอิน, เติมเงิน+อนุมัติ)
# =========================================================
set -e

WEB_ROOT="/var/www/chaiya"
API_DIR="/opt/chaiya-promo-api"
SERVICE_NAME="chaiya-promo-api"
API_PORT="5055"
ADMIN_PASSWORD="${ADMIN_PASSWORD:-chaiya2569}"   # เปลี่ยนได้: ADMIN_PASSWORD=xxxx bash install.sh

echo "==> สร้างโฟลเดอร์เว็บ: $WEB_ROOT"
mkdir -p "$WEB_ROOT"
mkdir -p "$API_DIR"
mkdir -p "$API_DIR/slips"

echo "==> เขียนไฟล์หน้าเว็บ (index / network-packages / login / wallet / admin)"
echo "" | base64 -d > "$WEB_ROOT/index.html"
echo "" | base64 -d > "$WEB_ROOT/network-packages.html"
echo "" | base64 -d > "$WEB_ROOT/login.html"
echo "" | base64 -d > "$WEB_ROOT/wallet.html"
echo "" | base64 -d > "$WEB_ROOT/admin.html"

echo "==> เขียน backend API (Flask)"
echo "" | base64 -d > "$API_DIR/app.py"

if [ ! -f "$API_DIR/promotions_data.json" ]; then
  echo "" | base64 -d > "$API_DIR/promotions_data.json"
  echo "    (สร้าง promotions_data.json ใหม่)"
else
  echo "    (พบ promotions_data.json เดิมอยู่แล้ว - ไม่เขียนทับ ข้อมูลโปรเดิมปลอดภัย)"
fi
echo "    (users.json / topups.json / tokens.json จะถูกสร้างอัตโนมัติตอน API เริ่มทำงานครั้งแรก - ถ้ามีอยู่แล้วจะไม่ถูกแตะ)"

echo "==> ติดตั้ง python venv + dependencies"
if ! command -v python3 >/dev/null; then
  apt-get update -y && apt-get install -y python3 python3-venv python3-pip
fi
python3 -m venv "$API_DIR/venv" 2>/dev/null || true
"$API_DIR/venv/bin/pip" install --upgrade pip -q
"$API_DIR/venv/bin/pip" install flask flask-cors -q

echo "==> ตั้งค่า systemd service: $SERVICE_NAME"
cat > "/etc/systemd/system/${SERVICE_NAME}.service" << SERVICEEOF
[Unit]
Description=ChaiyaVPN Promo/Wallet API
After=network.target

[Service]
Type=simple
WorkingDirectory=${API_DIR}
Environment=ADMIN_PASSWORD=${ADMIN_PASSWORD}
ExecStart=${API_DIR}/venv/bin/python3 ${API_DIR}/app.py
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
SERVICEEOF

systemctl daemon-reload
systemctl enable "$SERVICE_NAME" >/dev/null 2>&1
systemctl restart "$SERVICE_NAME"

sleep 1
if systemctl is-active --quiet "$SERVICE_NAME"; then
  echo "==> API ทำงานอยู่ที่ port $API_PORT (systemctl status $SERVICE_NAME)"
else
  echo "!! API ไม่ start ตรวจสอบด้วย: journalctl -u $SERVICE_NAME -n 50"
fi

echo ""
echo "=========================================================="
echo " เสร็จแล้ว! ไฟล์เว็บอยู่ที่ $WEB_ROOT"
echo " API รันที่ 127.0.0.1:$API_PORT (systemd: $SERVICE_NAME)"
echo " รหัสแอดมิน: $ADMIN_PASSWORD"
echo ""
echo " *** อย่าลืมแก้เลขบัญชีธนาคารใน $WEB_ROOT/wallet.html ก่อนใช้งานจริง ***"
echo ""
echo " ยังต้องเพิ่ม nginx config เอง (ครั้งเดียว) ถ้ายังไม่มี:"
echo ""
echo "   server {"
echo "       ...(server block เดิมของคุณ)..."
echo "       root $WEB_ROOT;"
echo "       location /api/ {"
echo "           proxy_pass http://127.0.0.1:$API_PORT;"
echo "           proxy_set_header Host \$host;"
echo "           client_max_body_size 8m;"
echo "       }"
echo "   }"
echo ""
echo " แล้วรัน: nginx -t && systemctl reload nginx"
echo "=========================================================="
